import io.github.vmzakharov.ecdataframe.dsl.*;
import io.github.vmzakharov.ecdataframe.util.CollectingPrinter;
import io.github.vmzakharov.ecdataframe.util.PrinterFactory;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class PrettyPrintVisitorTest {

    @Test
    public void visitAssignExprTest() {
        AssignExpr assignExpr = new AssignExpr(new VarExpr("var"), new Value("value"));
        assertEquals("var = value", PrettyPrintVisitor.exprToString(assignExpr));
    }

    @Test
    public void visitBinaryExprTest() {
        BinaryExpr binaryExpr = new BinaryExpr(new VarExpr("var1"), new VarExpr("var2"), BinaryOp.PLUS);
        assertEquals("var1 + var2", PrettyPrintVisitor.exprToString(binaryExpr));
    }

    @Test
    public void visitUnaryExprTest() {
        UnaryExpr unaryExpr = new UnaryExpr(new VarExpr("var"), UnaryOp.MINUS);
        assertEquals("-var", PrettyPrintVisitor.exprToString(unaryExpr));
    }

    @Test
    public void visitConstExprTest() {
        Value value = new Value("testValue");
        assertEquals("testValue", PrettyPrintVisitor.exprToString(value));
    }

    @Test
    public void visitFunctionCallExprTest() {
        FunctionCallExpr functionCallExpr = new FunctionCallExpr("functionName", new Expression[0]);
        assertEquals("functionName()", PrettyPrintVisitor.exprToString(functionCallExpr));
    }

    @Test
    public void visitPropertyPathExprTest() {
        PropertyPathExpr propertyPathExpr = new PropertyPathExpr("value");
        assertEquals("value", PrettyPrintVisitor.exprToString(propertyPathExpr));
    }

    @Test
    public void visitAnonymousScriptExprTest() {
        AnonymousScript anonymousScript = new AnonymousScript();
        assertEquals("", PrettyPrintVisitor.exprToString(anonymousScript));
    }

    @Test
    public void visitFunctionScriptExprTest() {
        FunctionScript functionScript = new FunctionScript("functionName", new String[0], new Statement[0]);
        assertEquals("functionName() {\n}", PrettyPrintVisitor.exprToString(functionScript));
    }

    @Test
    public void visitStatementSequenceScriptTest() {
        StatementSequenceScript statementSequenceScript = new StatementSequenceScript(new Statement[0]);
        assertEquals("", PrettyPrintVisitor.exprToString(statementSequenceScript));
    }

    @Test
    public void visitVarExprTest() {
        VarExpr varExpr = new VarExpr("variableName");
        assertEquals("variableName", PrettyPrintVisitor.exprToString(varExpr));
    }

    @Test
    public void visitProjectionExprTest() {
        ProjectionExpr projectionExpr = new ProjectionExpr("value");
        assertEquals("value", PrettyPrintVisitor.exprToString(projectionExpr));
    }

    @Test
    public void visitAliasExprTest() {
        AliasExpr aliasExpr = new AliasExpr("aliasName", new VarExpr("var"));
        assertEquals("aliasName as var", PrettyPrintVisitor.exprToString(aliasExpr));
    }

    @Test
    public void visitVectorExprTest() {
        VectorExpr vectorExpr = new VectorExpr();
        assertEquals("[]", PrettyPrintVisitor.exprToString(vectorExpr));
    }

    @Test
    public void visitIndexExprTest() {
        IndexExpr indexExpr = new IndexExpr(new VarExpr("var"), 1);
        assertEquals("var[1]", PrettyPrintVisitor.exprToString(indexExpr));
    }

    @Test
    public void visitDecimalExprTest() {
        DecimalExpr decimalExpr = new DecimalExpr(1.0);
        assertEquals("1.0", PrettyPrintVisitor.exprToString(decimalExpr));
    }

    @Test
    public void visitIfElseExprTest() {
        IfElseExpr ifElseExpr = new IfElseExpr(new VarExpr("var"), new Value("true"), new Value("false"));
        assertEquals("if (var) then true else false", PrettyPrintVisitor.exprToString(ifElseExpr));
    }

}
